using System.Collections.ObjectModel;using System.Windows.Input;using WAID.Application.Abstractions;using WAID.KnowledgeBase;namespace WAID.Desktop.ViewModels;public sealed class KnowledgeViewModel(IKnowledgeRetrievalService knowledge,IScanRepository scans):ViewModelBase{private AsyncCommand? _search;private string _query="";private string _status="Search the curated offline Windows knowledge base.";public ObservableCollection<KnowledgeSearchResult> Results{get;}=[];public string Query{get=>_query;set=>Set(ref _query,value);}public string Status{get=>_status;private set=>Set(ref _status,value);}public ICommand SearchCommand=>_search??=new(SearchAsync);private async Task SearchAsync(){try{var findings=(await scans.GetRecentAsync(5,CancellationToken.None)).SelectMany(x=>x.Findings).ToArray();var results=knowledge.Search(new(Query,Environment.OSVersion.Version.ToString(),findings.Select(x=>x.Code).ToArray()));Results.Clear();foreach(var result in results)Results.Add(result);Status=$"Found {Results.Count} offline article(s). Repair guidance appears only for trusted WAID or official content.";}catch(Exception e){Status=$"Knowledge search could not complete: {e.Message}";}}}